-- =============================================================================================
-- BizApps Sales v6.31.x -- Metadata_Sync (Sales Contacts FirstName is not a name field)
-- =============================================================================================
-- Generated by `mj sync push --dir metadata --ci` (MJ CLI 6.2.1) against a database built from
-- migrations ONLY (the v6.28.x seed build base, then this app's migrations at `next`). Push result:
-- 0 created, 96 updated, 223 unchanged, 0 errors; one statement changed a row.
--
-- UPDATED: Sales Contacts' FirstName field gets AutoUpdateIsNameField = 0
-- (metadata/entity-fields/.sales-contact-name-field.json). Without it CodeGen can flag FirstName as
-- a second name field when it adds fields to Sales Contacts, and every denormalized contact-name
-- column then shows a bare first name instead of DisplayNameAndEmail.
--
-- ADDED BY HAND: IsNameField = 0, which the metadata file also sets. The build database already had
-- it at 0 from the captured CodeGen SQL, so the push left it out; a host where CodeGen had already
-- flagged FirstName would otherwise keep the flag with auto-update switched off.
--
-- LOOKUP: the field's ID is resolved on the target database by entity name + field name, not
-- shipped as a literal, because entity field IDs can differ between databases. Nothing happens
-- when the field is missing. Idempotent.
-- =============================================================================================

-- Save MJ: Entity Fields (core SP call only)
DECLARE @IsNameField_80ba1c8ddc78 BIT,
@AutoUpdateIsNameField_80ba1c8ddc78 BIT,
@ID_80ba1c8ddc78 UNIQUEIDENTIFIER
SET
  @IsNameField_80ba1c8ddc78 = 0
SET
  @AutoUpdateIsNameField_80ba1c8ddc78 = 0
SELECT TOP 1 @ID_80ba1c8ddc78 = ef.[ID]
  FROM [${mjSchema}].[EntityField] ef
  JOIN [${mjSchema}].[Entity] e ON e.[ID] = ef.[EntityID]
 WHERE e.[Name] = N'MJ_BizApps_Sales: Sales Contacts' AND ef.[Name] = N'FirstName'
IF @ID_80ba1c8ddc78 IS NOT NULL
BEGIN
  EXEC [${mjSchema}].spUpdateEntityField @IsNameField = @IsNameField_80ba1c8ddc78,
    @AutoUpdateIsNameField = @AutoUpdateIsNameField_80ba1c8ddc78,
    @ID = @ID_80ba1c8ddc78;
END
